using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;

    vector<int> a, b, c;

    while (m != 0) {
        c.push_back(m % 3);
        m /= 3;
    }

    while (n != 0) {
        a.push_back(n % 3);
        n /= 3;
    }

    size_t length = max(a.size(), c.size());
    a.resize(length, 0);
    c.resize(length, 0);

    for (size_t i = 0; i < length; ++i) {
        b.push_back((c[i] - a[i] + 3) % 3);
    }

    reverse(b.begin(), b.end());

    long long sum = 0;
    for (int digit : b) {
        sum = sum * 3 + digit;
    }

    cout << sum;
    return 0;
}

